import styled from '@emotion/styled';
import { Heading, Paragraph } from 'components/UI';
import { theme } from 'theme';

export const StyledTitle = styled(Heading)({
  fontWeight: 'bold',
  height: 'auto',
  fontFamily: theme.fonts.heading,
  color: theme.colors.interfaceLabelPrimary,
});

type StyledParagraphSize = 'xsmall' | 'small' | 'medium' | 'large';
type StyledParagraphColor = 'primary' | 'secondary';

interface StyledParagraphProps {
  $size?: StyledParagraphSize;
  $color?: StyledParagraphColor;
  $overflow?: boolean;
}

export const StyledParagraph = styled(Paragraph, {
  shouldForwardProp: (propName) =>
    !['$size', '$color', '$overflow'].includes(propName),
})<StyledParagraphProps>(({ $size, $color, $overflow }) => ({
  fontSize: '14px !important',
  fontWeight: '400',
  fontFamily: theme.fonts.paragraph,
  color: '#5C5C5C',
  margin: 0,
  ...($size === 'xsmall' && { fontSize: '10px !important' }),
  ...($size === 'small' && { fontSize: '12px !important' }),
  ...($size === 'medium' && { fontSize: '14px !important' }),
  ...($size === 'large' && { fontSize: '16px !important' }),
  ...($color === 'primary' && { color: 'rgba(0,0,0,0.9) !important' }),
  ...($color === 'secondary' && { color: 'rgba(0,0,0,0.55) !important' }),
  ...($overflow && {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  }),
}));

type StyledSubtitleType = 'heading' | 'paragraph';

interface StyledSubtitleProps {
  $type?: StyledSubtitleType;
}

export const StyledSubtitle = styled('p', {
  shouldForwardProp: (propName) => propName !== '$type',
})<StyledSubtitleProps>(({ $type }) => ({
  fontFamily: theme.fonts.heading,
  fontSize: '16px',
  fontWeight: '600',
  color: 'rgba(20, 20, 20, 0.56)',
  margin: 0,
  ...($type === 'heading' && { fontFamily: theme.fonts.heading }),
  ...($type === 'paragraph' && { fontFamily: theme.fonts.paragraph }),
}));

export const StyledSectionTitle = styled(Heading)({
  fontSize: '20px !important',
});

interface StyledLabelProps {
  $error?: boolean;
}

export const StyledLabel = styled('label', {
  shouldForwardProp: (propName) => propName !== '$error',
})<StyledLabelProps>(({ $error }) => ({
  fontSize: '14px',
  fontWeight: '600',
  fontFamily: theme.fonts.paragraph,
  ...($error && { color: '#e82727' }),
}));

export const StyledOptionalFlag = styled.span({
  color: theme.colors.txt.secondary,
  fontSize: '14px',
  fontWeight: '400',
  fontFamily: theme.fonts.paragraph,
});

export const StyledErrorLabel = styled.span({
  fontSize: '12px',
  fontWeight: '600',
  color: '#e82727',
  fontFamily: theme.fonts.paragraph,
  display: 'flex',
  alignItems: 'center',
  gap: '4px',
});

type StyledMeasureSize = 'smallest' | 'small' | 'medium' | 'large';
type StyledMeasureColor = 'gray' | 'black';
type StyledMeasureWeight = 'light' | 'regular' | 'bold' | 'medium';

interface StyledMeasureProps {
  $size?: StyledMeasureSize;
  $color?: StyledMeasureColor;
  $weight?: StyledMeasureWeight;
}

export const StyledMeasure = styled('p', {
  shouldForwardProp: (propName) =>
    !['$size', '$color', '$weight'].includes(propName),
})<StyledMeasureProps>(({ $size, $color, $weight }) => ({
  fontSize: '1rem',
  color: theme.colors.interfaceLabelPrimary,
  margin: 0,
  fontFamily: theme.fonts.paragraph,
  ...($size === 'smallest' && { fontSize: '0.75rem !important' }),
  ...($size === 'small' && { fontSize: '0.875rem !important' }),
  ...($size === 'medium' && { fontSize: '1rem !important' }),
  ...($size === 'large' && { fontSize: '1.25rem !important' }),
  ...($color === 'gray' && { color: theme.colors.interfaceLabelSecondary }),
  ...($color === 'black' && { color: theme.colors.interfaceLabelPrimary }),
  ...($weight === 'light' && { fontWeight: 'light' }),
  ...($weight === 'regular' && { fontWeight: 'regular' }),
  ...($weight === 'bold' && { fontWeight: 'bold' }),
  ...($weight === 'medium' && { fontWeight: '500' }),
}));

type StyledRefreshLabelFontColor = 'primary' | 'secondary';
type StyledRefreshLabelSize = 'small' | 'medium' | 'large';

interface StyledRefreshLabelProps {
  $marginTop?: boolean;
  $fontColor?: StyledRefreshLabelFontColor;
  $size?: StyledRefreshLabelSize;
}

export const StyledRefreshLabel = styled('span', {
  shouldForwardProp: (propName) =>
    !['$marginTop', '$fontColor', '$size'].includes(propName),
})<StyledRefreshLabelProps>(
  ({ $marginTop, $fontColor = 'secondary', $size }) => ({
    fontWeight: '400',
    fontSize: '10px',
    fontFamily: theme.fonts.paragraph,
    lineHeight: '12px',
    ...($marginTop && { marginTop: theme.spacing['1'] }),
    ...($fontColor === 'primary' && { color: theme.colors.txt.default }),
    ...($fontColor === 'secondary' && { color: theme.colors.txt.secondary }),
    ...($size === 'small' && { fontSize: '10px' }),
    ...($size === 'medium' && { fontSize: '12px' }),
    ...($size === 'large' && { fontSize: '14px' }),
  }),
);

export const StyledTooltip = styled(Paragraph)({
  width: '100%',
});
